typedef struct {unsigned char *memory;VZKernelVM *vm;VZKernelCPU *cpu;uint64_t vmEpoch,publicID;VZKernelLifecycleResult life;VZKernelInitWriter writer;unsigned writes,reads;} Mock;
static uint64_t Thread(void *unused){(void)unused;uint64_t id=0;CHECK(!pthread_threadid_np(NULL,&id));return id;}
static int32_t Trap(void *opaque,uint64_t operation,void *args){Mock *m=opaque;if(operation==6){CHECK(args&&!((uint64_t *)args)[0]&&!((uint64_t *)args)[1]);memset(m->memory,0,0x8000);uint64_t version=VZ_KERNEL_NATIVE_CONTEXT_VERSION;memcpy(m->memory+0x4000,&version,8);((uint64_t *)args)[1]=(uintptr_t)m->memory;}else CHECK(operation==1||operation==2||operation==7);return 0;}
static bool Read(void *opaque,const void *address,size_t bytes,void *out){Mock *m=opaque;uintptr_t off=(uintptr_t)address-(uintptr_t)m->memory;CHECK(off<=0x8000&&bytes<=0x8000-off);++m->reads;memcpy(out,address,bytes);return true;}
static bool Write(void *opaque,void *address,size_t bytes,const void *value){Mock *m=opaque;uintptr_t off=(uintptr_t)address-(uintptr_t)m->memory;CHECK(off<=0x8000&&bytes<=0x8000-off);++m->writes;memcpy(address,value,bytes);return true;}
static void CreateCPU(Mock *m){CHECK(!VZKernelCPUCreate(m->vm,&m->cpu,&m->life));VZKernelCreationConfigV6 config={1,0,0,0,0,UINT64_C(0x123),UINT64_C(0x456),1};VZKernelInitReceipt receipt={0};CHECK(!VZKernelCPUApplyCreationConfigV6(m->cpu,&config,&m->writer,&receipt,&m->life));CHECK(!VZKernelCPUPublishIdentityV5(m->cpu,&m->publicID));}
static VZKernelRunPendingRequestV14 Identity(Mock *m){return (VZKernelRunPendingRequestV14){1,VZ_KERNEL_PROFILE_IPADOS_16_1_1,1,0,m->vmEpoch,m->publicID,m->life.ownerThread,m->life.generation,m->life.returnedSlotWord};}
static int Control(Mock *m,unsigned action,unsigned field,uint64_t value,uint64_t *out){VZKernelControlRequestV22 q={Identity(m),action,field,value};VZKernelInitReceipt receipt={0};VZKernelLifecycleResult life={0};return VZKernelCPUAccessControlV22(m->cpu,&q,&m->writer,out,&receipt,&life);}
static int SYS(Mock *m,unsigned action,unsigned field,uint64_t value,uint64_t *out){VZKernelSysRequest q={1,VZ_KERNEL_PROFILE_IPADOS_16_1_1,m->life.ownerThread,m->life.generation,m->life.returnedSlotWord,1,action,field,value};VZKernelSysReceipt receipt={0};VZKernelLifecycleResult life={0};int result=VZKernelCPUAccessSystemRegister(m->cpu,&q,&m->writer,out,&receipt,&life);CHECK(!receipt.attemptedNativeWrites&&!receipt.attemptedNativeReads);return result;}
static void *Foreign(void *p){Mock *m=p;uint64_t out=UINT64_C(0xabc);CHECK(Control(m,VZ_KERNEL_CONTROL_READ_V22,0,0,&out)!=VZ_KERNEL_OK&&out==UINT64_C(0xabc));return NULL;}
int main(void){Mock m={0};m.memory=mmap(NULL,0x8000,PROT_READ|PROT_WRITE,MAP_ANON|MAP_PRIVATE,-1,0);CHECK(m.memory!=MAP_FAILED);m.writer=(VZKernelInitWriter){&m,Write};VZKernelLifecycleOps ops={1,VZ_KERNEL_PROFILE_IPADOS_16_1_1,&m,Trap,Thread,Read};VZKernelVMOptions options={36,0,1,false,false};CHECK(!VZKernelVMCreate(&ops,&options,&m.vm,&m.life));m.vmEpoch=m.life.generation;CreateCPU(&m);
 uint64_t control0=UINT64_C(0xa123456789abcdef)|(UINT64_C(1)<<20)|(UINT64_C(1)<<18),control9=UINT64_C(0xa123456789abcdee),sync=UINT64_C(0x123456789abcdef0),dirty=UINT64_C(0x8123456789abcdef);memcpy(m.memory+0x670,&control0,8);memcpy(m.memory+0x6f0,&control9,8);memcpy(m.memory+0x678,&sync,8);memcpy(m.memory+0x748,&dirty,8);uint64_t out=0;
 CHECK(!Control(&m,VZ_KERNEL_CONTROL_READ_V22,0,0,&out)&&out==control0);CHECK(!Control(&m,VZ_KERNEL_CONTROL_WRITE_V22,0,out&~(UINT64_C(1)<<20),NULL));uint64_t actual=0;memcpy(&actual,m.memory+0x670,8);CHECK(actual==(control0&~(UINT64_C(1)<<20)));memcpy(&actual,m.memory+0x678,8);CHECK(actual==(sync|(UINT64_C(1)<<56)));memcpy(&actual,m.memory+0x748,8);CHECK(actual==(dirty|4));
 CHECK(!Control(&m,VZ_KERNEL_CONTROL_READ_V22,9,0,&out)&&out==control9);CHECK(!Control(&m,VZ_KERNEL_CONTROL_WRITE_V22,9,out|1,NULL));memcpy(&actual,m.memory+0x6f0,8);CHECK(actual==(control9|1));
 pthread_t other;CHECK(!pthread_create(&other,NULL,Foreign,&m));CHECK(!pthread_join(other,NULL));
 const unsigned ids[]={0xc028,0xc029,0xc030,0xc031,0xc032,0xc038,0xc039,0xc03a,0xc03b,0xc03c,0xc020,0xc021,0xc022,0xc025,0xc024};unsigned before=m.writes;
 for(unsigned i=0;i<15;++i){out=UINT64_C(0xfeedface);CHECK(SYS(&m,VZ_KERNEL_SYS_READ,ids[i],0,&out)==VZ_KERNEL_UNSUPPORTED&&out==UINT64_C(0xfeedface));CHECK(SYS(&m,VZ_KERNEL_SYS_WRITE,ids[i],1,NULL)==VZ_KERNEL_UNSUPPORTED);CHECK(!SYS(&m,VZ_KERNEL_SYS_WRITE,ids[i],0,NULL));out=1;CHECK(!SYS(&m,VZ_KERNEL_SYS_READ,ids[i],0,&out)&&out==0);CHECK(SYS(&m,VZ_KERNEL_SYS_WRITE,ids[i],UINT64_MAX,NULL)==VZ_KERNEL_UNSUPPORTED);out=1;CHECK(!SYS(&m,VZ_KERNEL_SYS_READ,ids[i],0,&out)&&out==0);}CHECK(m.writes==before);
 CHECK(!VZKernelCPUUnpublishIdentityV5(m.cpu));CHECK(!VZKernelCPUDestroy(m.cpu,&m.life));CHECK(!VZKernelCPUFree(m.cpu));CreateCPU(&m);for(unsigned i=0;i<15;++i){out=123;CHECK(SYS(&m,VZ_KERNEL_SYS_READ,ids[i],0,&out)==VZ_KERNEL_UNSUPPORTED&&out==123);}CHECK(!VZKernelCPUUnpublishIdentityV5(m.cpu));CHECK(!VZKernelCPUDestroy(m.cpu,&m.life));CHECK(!VZKernelCPUFree(m.cpu));CHECK(!VZKernelVMDestroy(m.vm,&m.life));CHECK(!VZKernelVMFree(m.vm));CHECK(!munmap(m.memory,0x8000));puts("{\"control0TrueNative670\":true,\"control9TrueNative6f0\":true,\"rmwUnrelatedBitsPreserved\":true,\"nativeSynchronizationOrderPreserved\":true,\"wrongOwnerRejected\":true,\"sixExplicitRequestedZeroCaches\":true,\"freshAndNonzeroUnsupported\":true,\"all15StartupFeatureIDsCovered\":true,\"featureCachesNoNativeWrites\":true,\"cleanupNewGenerationFresh\":true,\"nativeCallsExecuted\":0,\"deviceOperations\":0}");return 0;}
